package ama.storage;
import ama.contract.TranscriptContracts.*;import ama.contract.MinutesContracts.Mark;import org.junit.jupiter.api.Test;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.nio.file.Files;
import static org.junit.jupiter.api.Assertions.*;
class Task06FixLocksIT extends Task06FixFixture {
 @Test void retainedCompleteSetsDefaultIsolation()throws Exception{exercise(null);}
 @Test void retainedCompleteSetsReadCommitted()throws Exception{exercise(java.sql.Connection.TRANSACTION_READ_COMMITTED);}
 void exercise(Integer isolation)throws Exception {
  probe.isolation=isolation;String raw=raw();var ids=j.queryForList("SELECT segment_id FROM transcript_segment WHERE revision_id=? ORDER BY ordinal",String.class,raw);String working=resultId(isolated().mutate(actor(),meeting,"marked",new Command(Operation.SAVE,1,raw,List.of(new Edit(ids.get(0),"Lock😀",List.of(Mark.KEY)),new Edit(ids.get(1),"Second",List.of()))),UUID.randomUUID().toString()),"revisionId");String file=j.queryForObject("SELECT source_file_id FROM transcript_segment WHERE revision_id=? LIMIT 1",String.class,raw);var phase=new AtomicInteger();var created=new AtomicReference<String>();var observations=new CopyOnWriteArrayList<Object>();
  probe.afterBound=(sql,args)->{
   if(sql.startsWith("INSERT INTO transcript_revision("))created.set((String)args.get(1));
   if(!sql.contains("FROM transcript_segment_mark")||!sql.contains("FOR UPDATE")||!(working.equals(args.get(1))||Objects.equals(created.get(),args.get(1))))return;
   int at=phase.incrementAndGet();String selected=(String)args.get(1);try(var writers=Executors.newFixedThreadPool(5)){
    var futures=new ArrayList<Future<?>>();for(int action=0;action<5;action++){int kind=action;futures.add(writers.submit(()->{try(var connection=probe.actual.getConnection()){connection.setAutoCommit(false);if(isolation!=null)connection.setTransactionIsolation(isolation);try(var setting=connection.createStatement()){setting.execute("SET SESSION innodb_lock_wait_timeout=2");}String statement=switch(kind){case 0->"UPDATE transcript_segment SET body='grown' WHERE revision_id=? AND segment_id=?";case 1->"INSERT INTO transcript_segment(revision_id,segment_id,ordinal,body,source_file_id,source_paragraph) VALUES (?,?,999,'extra',?,999)";case 2->"INSERT INTO transcript_segment_mark VALUES (?,?,'KEY')";case 3->"UPDATE transcript_segment_mark SET mark='CONCLUSION' WHERE revision_id=? AND segment_id=? AND mark='KEY'";default->"DELETE FROM transcript_segment_mark WHERE revision_id=? AND segment_id=? AND mark='KEY'";};boolean blocked=false;long begin=System.nanoTime();try(var write=connection.prepareStatement(statement)){write.setString(1,selected);write.setString(2,kind==1?UUID.randomUUID().toString():kind==2?ids.get(1):ids.get(0));if(kind==1)write.setString(3,file);write.executeUpdate();}catch(java.sql.SQLException e){blocked=e.getErrorCode()==1205||e.getErrorCode()==1213;}finally{connection.rollback();}assertTrue(blocked,"phase="+at+" writer="+kind);observations.add(Map.of("phase",at,"writer",kind,"blocked",true,"elapsedMillis",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-begin)));}catch(Exception e){throw new RuntimeException(e);}}));}for(var future:futures)future.get(8,TimeUnit.SECONDS);
   }catch(Exception e){throw new RuntimeException(e);}
  };
  var service=isolated();service.readOwner(actor(),meeting,working);assertEquals(2,phase.get());var result=service.mutate(actor(),meeting,"locked-save",new Command(Operation.SAVE,2,working,List.of(new Edit(ids.get(0),"After",List.of(Mark.KEY)),new Edit(ids.get(1),"Second",List.of()))),UUID.randomUUID().toString());probe.afterBound=(sql,args)->{};assertEquals(5,phase.get());assertEquals(25,observations.size());assertEquals(2,j.queryForObject("SELECT COUNT(*) FROM transcript_segment WHERE revision_id=?",Integer.class,resultId(result,"revisionId")));assertEquals(1,j.queryForObject("SELECT COUNT(*) FROM transcript_segment_mark WHERE revision_id=?",Integer.class,resultId(result,"revisionId")));
  Files.writeString(receipt.resolve("all-phase-contention.json"),json.writeValueAsString(Map.of("isolation",isolation==null?"driver-default":isolation,"phases",List.of("READ_S","READ_F","COMMAND_S","COMMAND_F","READBACK"),"writers",List.of("body-update","segment-FK-insert","empty-mark-FK-insert","mark-update","mark-delete"),"observations",observations)));
 }
}
